-- --- Raccourcis, tranche 4/6 (42) ---
-- Les colonnes factorisees sont relues dans leur dictionnaire par indice :
-- chaque phrase partagee n'apparait qu'une fois par tranche. Chaque tranche
-- est applicable seule, ce qui permet de rejouer le catalogue morceau par
-- morceau lorsque le canal d'application limite la taille d'une requete.
insert into public.prompts (
  external_ref, command, name, slug, mode, category_id, short_description, intention,
  use_cases, usage_example, tags, required_variables, optional_variables, max_questions,
  minimal_context,
  sufficient_context,
  default_values,
  expected_output,
  output_format,
  quality_criteria,
  preserve_rules,
  avoid_rules,
  limitations,
  fallback_if_incomplete,
  usage_conditions,
  primary_input,
  accepted_inputs,
  attachment_rule,
  blocking_condition,
  questionnaire_mode,
  thumbnail_spec,
  thumbnail_layout,
  copy_rule,
  test_nominal,
  test_incomplete_context,
  test_blocking,
  input_type, output_type, risk_level, priority, source_status, catalog_version, revised_at,
  status, show_image_card, sort_order, published_at
)
select
  d.external_ref, d.command::extensions.citext, d.name, d.slug, d.mode::public.app_mode, c.id,
  d.short_description, d.intention,
  coalesce(d.use_cases, '{}'), d.usage_example, coalesce(d.tags, '{}'),
  coalesce(d.required_variables, '{}'), coalesce(d.optional_variables, '{}'),
  d.max_questions,
  ($raccourcia$["Sujet identifiable et transformation comprise.","Objectif et matière source ou brief compréhensibles."]$raccourcia$::jsonb ->> d.minimal_context_idx),
  ($raccourcia$["Sujet visible, zone/effet clair et aucune instruction contradictoire.","Objectif, audience ou destinataire, source et format déductibles du contexte."]$raccourcia$::jsonb ->> d.sufficient_context_idx),
  ($raccourcia$["Style photo/visualisation premium; format adapte a l'image source; fond neutre si non precise.","Conserver identité, cadrage et ratio; rendu réaliste premium.","Ton clair, direct et professionnel; longueur moyenne; structure scannable.","Ton clair professionnel; structure scannable; longueur moyenne.","Analyse factuelle; priorites classees; actions concretes; hypotheses signalees."]$raccourcia$::jsonb ->> d.default_values_idx),
  ($raccourcia$["Image finale ou prompt image final si l'interface ne permet pas l'edition directe.","Visuel final fidèle au sujet.","Texte final pret a publier, envoyer ou integrer.","Livrable textuel final et actionnable.","Analyse structuree avec constats, priorites et actions."]$raccourcia$::jsonb ->> d.expected_output_idx),
  ($raccourcia$["Image finale ou prompt image; aucune explication longue sauf blocage.","Image finale; sinon prompt image final prêt à exécuter.","Titre + texte final + variante courte si utile.","Texte final prêt à publier, envoyer ou intégrer.","Synthese, tableau des constats, priorites, recommandations."]$raccourcia$::jsonb ->> d.output_format_idx),
  ($raccourcia$["Sujet reconnaissable; rendu propre; consignes respectees; coherence lumiere/matiere; aucun artefact majeur.","Sujet reconnaissable; cohérence lumière/matière; effet visible; aucun artefact majeur; texte lisible ou absent.","Clarte; specificite; utilite immediate; ton adapte; zero remplissage; appel a l'action net si pertinent.","Exactitude; clarté; spécificité; structure; ton adapté; faits séparés des hypothèses.","Faits separes des hypotheses; priorisation; angles morts listes; recommandations actionnables."]$raccourcia$::jsonb ->> d.quality_criteria_idx),
  ($raccourcia$["Identite du sujet, proportions, angle general, lumiere coherente, materiaux plausibles.","Identité, proportions, éléments distinctifs, perspective et informations de marque fournies.","Intention, niveau de langage, informations fournies, contraintes de marque.","Intention, faits, chiffres, sources, contraintes et voix fournis.","Faits observables, incertitudes, limites de la source, distinction fait/inference."]$raccourcia$::jsonb ->> d.preserve_rules_idx),
  ($raccourcia$["Deformer le sujet, inventer des elements absurdes, changer l'identite, ajouter du texte illisible.","Déformations, membres/objets ajoutés, logos altérés, texte illisible, incohérences d'ombre.","Promesses non prouvees, ton generique, survente, invention de chiffres ou de sources.","Invention, remplissage, surpromesse, citation fictive, jargon et répétition.","Inventer des donnees, conclure sans preuve, masquer les hypotheses."]$raccourcia$::jsonb ->> d.avoid_rules_idx),
  ($raccourcia$["Les IA peuvent mal preserver les visages, logos, textes fins et details techniques microscopiques.","Résultat variable sur texte fin, logos, mains, visages et détails techniques; validation humaine requise.","Ne pas utiliser pour tromper, usurper ou creer une fausse situation sensible.","Ne remplace pas une validation juridique, medicale ou financiere; chiffres et sources doivent etre fournis.","La qualité dépend des sources; aucune validation juridique, médicale ou financière implicite.","Information generale uniquement; faire valider par un professionnel du droit.","La qualite depend fortement de la source; demander validation humaine pour decisions sensibles.","Ne constitue pas un avis juridique; validation professionnelle requise.","Information d'aide a la lecture uniquement; ne remplace pas un conseil financier.","Premier niveau uniquement; faire auditer par un expert pour exposition reelle."]$raccourcia$::jsonb ->> d.limitations_idx),
  ($raccourcia$["Demander une image ou un brief détaillé si le sujet ne peut pas être identifié.","Bloquer si aucune image source exploitable n'est jointe.","Poser uniquement les questions indispensables si l'objectif ou la matière source manque.","Demander la source manquante; ne jamais inventer son contenu.","Demander l'URL, la capture ou le contenu si la page n'est pas accessible.","Bloquer l'analyse chiffrée si aucune donnée lisible n'est fournie; proposer seulement la grille attendue."]$raccourcia$::jsonb ->> d.fallback_if_incomplete_idx),
  ($raccourcia$["Utiliser une image dont l'utilisateur détient les droits; obtenir le consentement pour un portrait identifiable; ne pas présenter une simulation comme une preuve.","Utiliser des données autorisées; anonymiser les informations sensibles; faire valider les domaines réglementés."]$raccourcia$::jsonb ->> d.usage_conditions_idx),
  ($raccourcia$["image","texte","document","URL ou document","tableau/données"]$raccourcia$::jsonb ->> d.primary_input_idx),
  ($raccourcia$["image; texte de contexte","texte; image de référence facultative","brief; texte; notes; document facultatif","pdf; docx; texte collé; image lisible","URL; capture; PDF; texte","xlsx; csv; tableau collé; document"]$raccourcia$::jsonb ->> d.accepted_inputs_idx),
