-- --- Categories v1 devenues sans objet --------------------------------
-- Archivees, jamais supprimees : leurs raccourcis ont deja rejoint la
-- taxonomie v2 juste au-dessus, et l'historique reste consultable.
--
-- Bornee aux categories de la v1, celles qui n'ont pas de reference externe.
-- Sans cette borne, l'instruction archive tout ce qu'elle ne connait pas :
-- rejouee apres la migration du socle V5, elle archivait les quatorze
-- familles neuves, vides par construction, que la bascule devra publier.
update public.categories
   set status = 'archived'
 where external_ref is null
   and slug not in (
   select d.slug from jsonb_to_recordset(
     $raccourcia$[{"slug":"image-technique-pedagogique"},{"slug":"image-produit-publicite"},{"slug":"image-retouche-transformation"},{"slug":"image-portrait-identite"},{"slug":"image-styles-effets"},{"slug":"texte-business-croissance"},{"slug":"texte-communication-contenu"},{"slug":"texte-travail-pilotage"},{"slug":"texte-produit-experience"},{"slug":"texte-apprentissage-carriere"},{"slug":"image-technique-pedagogique-vue-technique"},{"slug":"image-technique-pedagogique-information-visuelle"},{"slug":"image-produit-publicite-produit-e-commerce"},{"slug":"image-produit-publicite-campagnes-social"},{"slug":"image-retouche-transformation-retouche-ciblee"},{"slug":"image-retouche-transformation-lieux-lifestyle"},{"slug":"image-portrait-identite-portrait-beaute"},{"slug":"image-portrait-identite-mode-identite"},{"slug":"image-styles-effets-cinema-spectaculaire"},{"slug":"image-styles-effets-illustration-matieres"},{"slug":"texte-business-croissance-offre-strategie"},{"slug":"texte-business-croissance-marketing-acquisition"},{"slug":"texte-communication-contenu-marque-editorial"},{"slug":"texte-communication-contenu-relation-reseaux"},{"slug":"texte-travail-pilotage-documents-operations"},{"slug":"texte-travail-pilotage-analyser-decider"},{"slug":"texte-produit-experience-produit-ux"},{"slug":"texte-produit-experience-support-tech"},{"slug":"texte-apprentissage-carriere-carriere-recrutement"},{"slug":"texte-apprentissage-carriere-etudes-creativite"}]$raccourcia$::jsonb
   ) as d(slug text)
 )
   and status <> 'archived'
   and not exists (
     select 1 from public.prompts p
     where p.category_id = public.categories.id and p.status = 'published'
   );

-- --- Variantes par IA -------------------------------------------------
-- La capacite annoncee depend du mode, pas du raccourci : une ligne par
-- couple (mode, IA) suffit a produire les trois variantes de chaque prompt.
insert into public.prompt_variants (prompt_id, provider_id, compatibility, compatibility_note, status)
select p.id, pr.id, d.compatibility::public.compatibility_level, d.compatibility_note,
       d.status::public.content_status
from jsonb_to_recordset($raccourcia$[{"mode":"image","provider_key":"chatgpt","compatibility":"bon","compatibility_note":"Payload compatible; génération/édition selon outils activés.","status":"published"},{"mode":"image","provider_key":"claude","compatibility":"bon","compatibility_note":"Payload compatible; rendre le prompt final si l'édition d'image n'est pas disponible.","status":"published"},{"mode":"image","provider_key":"gemini","compatibility":"bon","compatibility_note":"Payload compatible; génération/édition selon outils activés.","status":"published"},{"mode":"texte","provider_key":"chatgpt","compatibility":"bon","compatibility_note":"Compatible texte et documents selon limites de contexte.","status":"published"},{"mode":"texte","provider_key":"claude","compatibility":"bon","compatibility_note":"Compatible texte et documents selon limites de contexte.","status":"published"},{"mode":"texte","provider_key":"gemini","compatibility":"bon","compatibility_note":"Compatible texte et documents selon limites de contexte.","status":"published"}]$raccourcia$::jsonb)
  as d(mode text, provider_key text, compatibility text,
       compatibility_note text, status text)
join public.prompts p on p.mode = d.mode::public.app_mode and p.external_ref like 'RCI-%'
join public.ai_providers pr on pr.key = d.provider_key
on conflict (prompt_id, provider_id) do update set
  compatibility = excluded.compatibility, compatibility_note = excluded.compatibility_note,
  status = excluded.status;

-- --- Versions de payload ----------------------------------------------
-- Le bloc numerote du prompt copiable est reconstruit depuis le QCM lui-meme :
-- stocker les deux serait stocker deux fois le meme texte. La table vit le
-- temps de la transaction, elle doit donc etre creee avec l'insertion.
create temporary table seed_qcm_sets on commit drop as
select
  d.key,
  d.qcm,
  (
    select string_agg(
      e.ord || '. ' || (e.item ->> 'question') || ' ' || (
        select string_agg(chr(64 + o::int) || '. ' || opt, ' ' order by o)
        from jsonb_array_elements_text(e.item -> 'options') with ordinality as t(opt, o)
      ),
      chr(10) order by e.ord
    )
    from jsonb_array_elements(d.qcm) with ordinality as e(item, ord)
  ) as qcm_block
from jsonb_to_recordset($raccourcia$[{"key":"qcm-1","qcm":[{"question":"Quel est le sujet principal à traiter ?","options":["Objet visible","Personne visible","Lieu ou scène","Autre"],"variable":"sujet","valeur_defaut":"Sujet dominant de la source"}]},{"key":"qcm-2","qcm":[{"question":"Quel est le sujet principal à traiter ?","options":["Objet visible","Personne visible","Lieu ou scène","Autre"],"variable":"sujet","valeur_defaut":"Sujet dominant de la source"},{"question":"Quelle précision donner pour « axe de coupe » ?","options":["Déduire de l'image","Conserver l'existant","Je précise","Autre"],"variable":"axe_de_coupe","valeur_defaut":"Déduire de la source"}]},{"key":"qcm-3","qcm":[{"question":"Quel est le sujet principal à traiter ?","options":["Objet visible","Personne visible","Lieu ou scène","Autre"],"variable":"sujet","valeur_defaut":"Sujet dominant de la source"},{"question":"Quelle zone doit être modifiée ?","options":["Sujet principal","Arrière-plan","Détail indiqué","Autre"],"variable":"zone","valeur_defaut":"Zone explicitement indiquée"}]},{"key":"qcm-4","qcm":[{"question":"Quel est le sujet principal à traiter ?","options":["Objet visible","Personne visible","Lieu ou scène","Autre"],"variable":"sujet","valeur_defaut":"Sujet dominant de la source"},{"question":"Quelle précision donner pour « densite » ?","options":["Déduire de l'image","Conserver l'existant","Je précise","Autre"],"variable":"densite","valeur_defaut":"Déduire de la source"}]},{"key":"qcm-5","qcm":[{"question":"Quel est le sujet principal à traiter ?","options":["Objet visible","Personne visible","Lieu ou scène","Autre"],"variable":"sujet","valeur_defaut":"Sujet dominant de la source"},{"question":"Quelle précision donner pour « zones » ?","options":["Déduire de l'image","Conserver l'existant","Je précise","Autre"],"variable":"zones","valeur_defaut":"Déduire de la source"}]},{"key":"qcm-6","qcm":[{"question":"Quel est le sujet principal à traiter ?","options":["Objet visible","Personne visible","Lieu ou scène","Autre"],"variable":"sujet","valeur_defaut":"Sujet dominant de la source"},{"question":"Quelle précision donner pour « mesures » ?","options":["Déduire de l'image","Conserver l'existant","Je précise","Autre"],"variable":"mesures","valeur_defaut":"Déduire de la source"}]},{"key":"qcm-7","qcm":[{"question":"Quelle précision donner pour « processus » ?","options":["Déduire de l'image","Conserver l'existant","Je précise","Autre"],"variable":"processus","valeur_defaut":"Déduire de la source"},{"question":"Quelle précision donner pour « etapes » ?","options":["Déduire de l'image","Conserver l'existant","Je précise","Autre"],"variable":"etapes","valeur_defaut":"Déduire de la source"}]},{"key":"qcm-8","qcm":[{"question":"Quel est le sujet principal à traiter ?","options":["Objet visible","Personne visible","Lieu ou scène","Autre"],"variable":"sujet","valeur_defaut":"Sujet dominant de la source"},{"question":"Quelle précision donner pour « points cles » ?","options":["Déduire de l'image","Conserver l'existant","Je précise","Autre"],"variable":"points_cles","valeur_defaut":"Déduire de la source"}]},{"key":"qcm-9","qcm":[{"question":"Quelle précision donner pour « options » ?","options":["Déduire de l'image","Conserver l'existant","Je précise","Autre"],"variable":"options","valeur_defaut":"Déduire de la source"},{"question":"Quelle précision donner pour « criteres » ?","options":["Déduire de l'image","Conserver l'existant","Je précise","Autre"],"variable":"criteres","valeur_defaut":"Déduire de la source"}]},{"key":"qcm-10","qcm":[{"question":"Quelle précision donner pour « processus » ?","options":["Déduire de l'image","Conserver l'existant","Je précise","Autre"],"variable":"processus","valeur_defaut":"Déduire de la source"}]},{"key":"qcm-11","qcm":[{"question":"Quelle précision donner pour « lieu » ?","options":["Déduire de l'image","Conserver l'existant","Je précise","Autre"],"variable":"lieu","valeur_defaut":"Déduire de la source"},{"question":"Quelle