-- La version precedente n'est jamais ecrasee : elle est retiree du courant
-- et reste consultable (Regle R12). Seules les variantes qui recoivent une
-- version v2.0 sont touchees.
update public.prompt_versions existing
   set is_current = false, status = 'retired'
  from public.prompt_variants v
  join public.prompts p on p.id = v.prompt_id
 where existing.variant_id = v.id
   and existing.is_current
   and existing.version_label <> $raccourcia$v2.0$raccourcia$
   and p.external_ref like 'RCI-%';

-- Les 250 payloads suivent un modele unique : plutot que de recopier 330 Ko
-- de texte, le seed porte le modele et Postgres le remplit depuis les champs
-- deja inseres. Le texte stocke est rigoureusement celui du catalogue
-- editorial (verifie octet par octet par tests/db/run.sh).
--
-- Le payload initial est identique pour les trois IA : chaque variante recoit
-- le meme texte. L'admin pourra ensuite faire diverger une version par IA
-- sans toucher au code.
insert into public.prompt_versions
  (variant_id, version_label, payload, qcm, qcm_trigger, status, is_current, published_at)
select
  v.id,
  d.version_label,
  format(
    $tpl$[RaccourcIA %s]
Rôle: exécuter « %s ».
Objectif: %s

1. CONTEXTE
Analyse d'abord le message, la conversation et les pièces jointes. N'invente aucune donnée. Si le contexte suffit, exécute immédiatement.
Entrée primaire: %s. Entrées acceptées: %s.
Variables indispensables: %s.

2. QUESTIONS CONDITIONNELLES
Mode: %s. Ne pose que les questions réellement bloquantes, maximum %s.
%s

3. EXÉCUTION
%s
Préserver: %s
Éviter: %s
Blocage: %s

4. SORTIE
%s

5. CONTRÔLE QUALITÉ
%s
Signale brièvement toute hypothèse ou limite qui change la fiabilité du résultat.$tpl$,
    p.command::text, p.name, p.intention,
    p.primary_input, p.accepted_inputs,
    array_to_string(p.required_variables, '; '),
    p.questionnaire_mode, p.max_questions, q.qcm_block,
    p.short_description, p.preserve_rules, p.avoid_rules, p.blocking_condition,
    p.output_format, p.quality_criteria
  ),
  q.qcm,
  ($raccourcia$["Uniquement si une variable indispensable ne peut pas être déduite avec confiance.","Seulement si la source ou l'instruction essentielle manque."]$raccourcia$::jsonb ->> d.qcm_trigger_idx),
  'published'::public.version_status, true, now()
from jsonb_to_recordset($raccourcia$[{"external_ref":"RCI-IMG-001","version_label":"v2.0","qcm_key":"qcm-1","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-002","version_label":"v2.0","qcm_key":"qcm-1","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-003","version_label":"v2.0","qcm_key":"qcm-2","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-004","version_label":"v2.0","qcm_key":"qcm-1","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-005","version_label":"v2.0","qcm_key":"qcm-1","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-006","version_label":"v2.0","qcm_key":"qcm-3","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-007","version_label":"v2.0","qcm_key":"qcm-1","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-008","version_label":"v2.0","qcm_key":"qcm-1","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-009","version_label":"v2.0","qcm_key":"qcm-1","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-010","version_label":"v2.0","qcm_key":"qcm-1","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-091","version_label":"v2.0","qcm_key":"qcm-1","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-092","version_label":"v2.0","qcm_key":"qcm-4","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-093","version_label":"v2.0","qcm_key":"qcm-5","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-094","version_label":"v2.0","qcm_key":"qcm-6","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-095","version_label":"v2.0","qcm_key":"qcm-7","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-044","version_label":"v2.0","qcm_key":"qcm-8","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-045","version_label":"v2.0","qcm_key":"qcm-9","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-046","version_label":"v2.0","qcm_key":"qcm-10","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-047","version_label":"v2.0","qcm_key":"qcm-11","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-048","version_label":"v2.0","qcm_key":"qcm-12","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-049","version_label":"v2.0","qcm_key":"qcm-5","qcm_trigger_idx":0},{"external_ref":"RCI-IMG-011